-- The same two indexes created the other way round: the unique index is first, so its
-- duplicate is the `23505`.
-- @setup
CREATE TABLE t (a text, b int);
CREATE UNIQUE INDEX t_b ON t (b);
CREATE INDEX t_a ON t (a);
INSERT INTO t VALUES ('x', 1);
-- @test
-- @expect-error: the earlier unique index refuses the duplicate
-- @expect-message
-- @profile-lock
INSERT INTO t VALUES ('', 1);
